// User-Auftrag ("nicht das System auto wechselt Sub mit Main, sondern der
// Spieler soll jeden Spieler selbst manuell einzeln ... zu MAIN, SUB,
// RESERVE wechseln können"): EIN gemeinsamer, symmetrischer Bewegungs-
// Mechanismus für alle 6 möglichen Richtungen zwischen den 3 Kategorien --
// ersetzt die alten swapKaderRosterSlot() (Starter<->Sub, IMMER blind mit
// dem einen Sub-Slot bzw. IMMER Starter-Slot 0) und promoteReservePlayer()
// (Reserve->Sub/Starter). Prinzip (aus Runde 125 übernommen, jetzt generisch
// für alle Richtungen): ist das Ziel noch nicht voll, wird einfach
// aufgefüllt (push), ist es voll, wird mit dem bisherigen Insassen getauscht
// (der wandert dann in die HERKUNFTS-Kategorie zurück) -- dadurch bleibt die
// Gesamtzahl in jeder Kategorie beim Tausch-Fall exakt erhalten, beim
// Ziel "Reserve" (reine Ergänzung, kein Gegenpart) wird stattdessen die
// 6er-Kapazitätsgrenze geprüft.
function moveKaderPerson(fromType, fromIndex, toType) {
  const roster = assignedOrg.roster;
  if (!roster || fromType === toType) return;
  const person = fromType === 'starters' ? roster.starters[fromIndex]
    : fromType === 'sub' ? roster.sub
    : roster.reserve[fromIndex];
  if (!person) return;

  if (toType === 'reserve') {
    if (reserveSlotsOccupied() >= KADER_RESERVE_SLOTS) {
      showConfirmModal('Reserve ist voll', 'Kein Platz mehr in der Reserve (' + KADER_RESERVE_SLOTS + '/' + KADER_RESERVE_SLOTS + ' Plätze belegt). Verkaufe zuerst jemanden.', () => {}, { hideCancel: true, confirmLabel: 'Verstanden' });
      return;
    }
    if (fromType === 'starters') roster.starters.splice(fromIndex, 1);
    else roster.sub = null;
    roster.reserve.push(person);
  } else if (toType === 'sub') {
    const demoted = roster.sub;
    if (fromType === 'starters') roster.starters.splice(fromIndex, 1);
    else roster.reserve.splice(fromIndex, 1);
    roster.sub = person;
    if (demoted) {
      if (fromType === 'starters') roster.starters.push(demoted);
      else roster.reserve.push(demoted);
    }
  } else if (toType === 'starters') {
    if (fromType === 'sub') roster.sub = null;
    else roster.reserve.splice(fromIndex, 1);
    if (roster.starters.length < MAIN_SIZE) {
      roster.starters.push(person);
    } else {
      const weakestIdx = roster.starters.reduce((minIdx, p, i, arr) => (p.overall < arr[minIdx].overall ? i : minIdx), 0);
      const demoted = roster.starters[weakestIdx];
      roster.starters[weakestIdx] = person;
      if (fromType === 'sub') roster.sub = demoted;
      else roster.reserve.push(demoted);
    }
  }

  assignedOrg.strength = computeOrgStrengthFromRoster(roster);
  saveGameState();
  renderDashboardKaderPanel();
}

// Bug-Fix (User-Meldung: "Man kann keine Spieler verkaufen bei Kader und/oder
// Transfer -- Option Verkauf hinzufügen, Geld soll bei Finanzen beim nicht
// eingeteilten Geld durch Verkauf landen"): es gab bisher überhaupt keinen
// erreichbaren Verkaufs-Mechanismus (nur Kaufen war gebaut, siehe
// executePlayerSigning()). Verkaufserlös = calculatePlayerTransferValue(person)
// (seit Bot-Ökosystem V8 potential-/altersbewusst statt nur calculatePrice()
// -- ein junges Talent mit Overall-Rückstand aber hohem Potential bringt
// jetzt spürbar mehr als ein gleich starker Spieler ohne Perspektive, exakt
// wie beim Kauf, spiegelbildlich). Da financeAllocation
// seit Runde 108 feste €-Beträge sind (nicht mehr automatisch anteilig
// verteilte Prozente), landet der Erlös automatisch VOLLSTÄNDIG bei "nicht
// eingeteiltes Geld" (financeUnallocated() = budget - Summe der 4 festen
// Kategorien) -- genau wie vom User verlangt, ohne dass eine der 4
// Kategorien mit erhöht werden muss.
function findKaderSlotPerson(slotType, index) {
  const roster = assignedOrg.roster;
  if (slotType === 'starters') return roster.starters[index];
  if (slotType === 'sub') return roster.sub;
  if (slotType === 'reserve') return roster.reserve[index];
  return null;
}

function sellRosterPlayer(slotType, index) {
  const person = findKaderSlotPerson(slotType, index);
  if (!person) return;
  if (!isTransferWindowOpen(careerDate)) {
    showConfirmModal('Transferfenster geschlossen', 'Verkäufe sind nur vom 1. Dezember bis 15. Januar möglich.', () => {}, { hideCancel: true, confirmLabel: 'Verstanden' });
    return;
  }
  const price = calculatePlayerTransferValue(person);
  // Bug-Fix (Audit): der Verkauf selbst warnte nie, wenn danach die
  // Turnier-Mindestgröße (3 Starter, siehe rosterMeetsTournamentMinimum())
  // unterschritten wird -- man merkte es bisher erst beim nächsten
  // Anmeldeversuch ("notEnoughPlayers"), ohne dass der auslösende Verkauf je
  // gewarnt hätte. Kein Softlock (das System fängt es ab), aber eine
  // vermeidbare Frustfalle -- nur beim Verkauf eines STARTERS relevant, Sub/
  // Reserve zählen nicht zur Mindestgröße.
  const wouldDropBelowMinimum = slotType === 'starters' && assignedOrg.roster.starters.length <= 3;
  const warningNote = wouldDropBelowMinimum
    ? ' ACHTUNG: Danach hast du weniger als 3 Starter und kannst dich für kein Turnier mehr anmelden, bis du nachverpflichtest.'
    : '';
  showConfirmModal(
    person.name + ' verkaufen?',
    'Du erhältst ' + formatMoney(price) + ' (Marktwert). ' + person.name + ' verlässt deinen Kader sofort und steht keinem anderen Team zur Verfügung.' + warningNote,
    () => executeSellRosterPlayer(slotType, index),
    { confirmLabel: 'Verkaufen' }
  );
}

function executeSellRosterPlayer(slotType, index) {
  const roster = assignedOrg.roster;
  const person = findKaderSlotPerson(slotType, index);
  if (!person) return;
  const price = calculatePlayerTransferValue(person);
  const roleLabel = slotType === 'starters' ? 'Starter' : slotType === 'sub' ? 'Sub' : 'Reserve';
  clearPersonDevelopmentEntry(assignedOrg.name, roleLabel, person.name);
  if (slotType === 'starters') roster.starters.splice(index, 1);
  else if (slotType === 'sub') roster.sub = null;
  else roster.reserve.splice(index, 1);
  assignedOrg.budget += price;
  // Bug-Fix (siehe logTransfer()-Kommentar): der verkaufte Spieler ist jetzt
  // aus dem Kader entfernt -- ohne Schnappschuss würde die Transfers-Seite
  // Rolle/Bewertung/Nation nicht mehr finden ("-" statt echter Werte).
  logTransfer(assignedOrg.name, 'Free Agent', person.name, price, { role: roleLabel, stars: npcStarRating(person.overall), country: person.country });
  addFinanceMonthlyIncome(price, 'Transfers', person.name + ' verkauft');
  pushPostMessage('transfers', 'NORMAL', 'Transferabteilung', 'Spieler verkauft', person.name + ' wurde für ' + formatMoney(price) + ' verkauft.', null, { type: 'openPage', page: 'transfers' });
  assignedOrg.strength = computeOrgStrengthFromRoster(roster);
  // Konsistenz-Ergänzung (Runde H): dritter, manueller Abgangs-Pfad -- greift
  // wie bei den beiden automatischen Pfaden NUR beim absoluten Nullpunkt
  // (letzter Starter/Sub/Reserve verkauft), die Warnung vor dem Verkauf bleibt
  // unverändert (echte Konsequenz), nur das dauerhafte Totalausfall-Risiko wird geschlossen.
  maybeEmergencyFillEmptyPlayerRoster(assignedOrg);
  saveGameState();
  renderDashboardKaderPanel();
  renderDashboardTopbar();
}

